cases.source:
case expr
  in [];
  in [x];
  in [x, ];
  in Foo::Bar[];
  in Foo();
  in Bar(*);
  in Bar(a, b, *c, d, e);
end

case expr
  in [*, x, *];
  in [*x, 1, 2, *y];
  in Foo::Bar[*, 1, *];
  in Foo(*, Bar, *);
end

case expr
  in {};
  in {x:};
  in Foo::Bar[ x:1 ];
  in Foo::Bar[ x:1, a:, **rest ];
  in Foo( y:);
  in Bar( ** );
  in Bar( a: 1, **nil);
end
